/* ============================================================
   order-detail.js — the Order page (Merchsmith Orders.html#order=<id>), Sep 2026 v2.
   One page, three views (MSID role): customer · distributor (+ admin) · supplier.
   Each ITEM carries its own supply flow (distributor + supplier see it on the item card):
     received → sent (checked & sent with artwork, visual, approved proof)
     → ack (supplier uploads Order Acknowledgement; distributor can upload it; must be CHECKED against the order)
     → proof (supplier uploads proof; distributor can upload it; must be CHECKED against the proof sent)
     → confirmed (customer gets confirmation, supplier gets proof approval)   ⟂ revision (In progress: customer
       reconfirms the change, distributor Re-processes → back to received)
     → prod (supplier acknowledges the approved proof) → dispatch (tracking: courier + number; customer notified)
     → delivered (courier confirms — simulated courier API; see HANDOVER).
   Store: ms-order-ops {orderId:{v:2, lines:[per-line state], pos:{supplier:{no,sentAt,invoice}}, chat, sup{}, notes, activity, problems, paid}}
   window.__odRender(root, order, role)
   ============================================================ */
